import { writeFileSync } from "node:fs";
import { workspaceSources } from "./workspace-sources.ts";
const source = workspaceSources();
const files = source.inputs.map(({ id, packageId }) => ({ id, packageId }));
const mappings = source.mappings.sort((a, b) =>
  a.packageId < b.packageId
    ? -1
    : a.packageId > b.packageId
      ? 1
      : a.specifier < b.specifier
        ? -1
        : a.specifier > b.specifier
          ? 1
          : 0,
);
writeFileSync(
  "packages/compiler/src/catalog.ts",
  '// Generated by tools/generate-compiler-catalog.ts from the workspace manifests.\nimport type {ImportMapping} from "@tint/source/resolver";\nexport interface ProjectFile {readonly id:string;readonly packageId:string;}\nexport function projectFiles():ProjectFile[]{return ' +
    JSON.stringify(files, null, 2) +
    ";}\nexport function projectMappings():ImportMapping[]{return " +
    JSON.stringify(mappings, null, 2) +
    ";}\n",
);
console.log(
  `Recorded ${files.length} source files and ${mappings.length} explicit import grants.`,
);
